// Original teaching text. Question numbers refer to the user's supplied practice DOCX.
const modules=[];
const range=(a,b)=>Array.from({length:b-a+1},(_,i)=>a+i);
function add(id,unit,questions,title,diagram,steps,pitfall,refs=[]){modules.push({id,unit,questions,title,diagram,steps:steps.map(([title,text,focus])=>({title,text,focus})),pitfall,refs})}
add('rankine',0,[1,10,12],'De la energía del combustible al trabajo del eje','rankine',[
 ['La bomba consume trabajo','El condensado líquido entra a la bomba. El eje le entrega trabajo para elevar su presión hasta superar la presión de alimentación y las pérdidas del circuito. Ese consumo reduce el trabajo neto; pequeño no significa nulo.','pump'],
 ['La caldera aporta calor','La combustión convierte energía química en energía térmica. El calor cruza las superficies de calefacción: el agua se calienta, evapora y, si hay sobrecalentador, el vapor aumenta su temperatura antes de entrar a la turbina.','boiler'],
 ['La turbina entrega trabajo','El vapor se expande y disminuye su entalpía. Toberas y álabes orientan y modifican su velocidad; el rotor recibe par y entrega potencia. Sobrecalentamiento y recalentamiento modifican la expansión y la humedad final; la regeneración precalienta alimentación con extracciones.','turbine'],
 ['El condensador cierra el ciclo','El vapor de escape cede calor a otra corriente y vuelve a líquido. La bomba devuelve ese líquido al generador. Bajar la presión de condensación aumenta el salto disponible, pero exige considerar refrigeración, vacío y humedad. Trabajo neto: turbina menos bomba.','condenser']
],'No confundas calor aportado con trabajo útil: parte del calor se rechaza en el condensador.');
add('estados',0,range(2,7),'Reconocer el estado del agua y del vapor','states',[
 ['Antes de hervir','A una presión dada, el líquido subenfriado tiene temperatura menor que la de saturación. Calor es energía transferida por diferencia de temperatura; temperatura describe el estado térmico. El calor sensible cambia temperatura sin cambio de fase.','liquid'],
 ['Dentro de la región de mezcla','A la saturación comienza la vaporización. A presión constante, el calor latente aumenta la fracción de vapor sin elevar la temperatura de equilibrio. El título x es masa de vapor dividida por masa total: x=0 líquido saturado; x=1 vapor saturado seco.','wet'],
 ['Después de secarse','Al aportar calor al vapor saturado seco aparece vapor sobrecalentado: T mayor que Tsat a esa presión. El título no se usa fuera de la región bifásica. El grado de sobrecalentamiento es T medida menos Tsat, no la temperatura del vapor por sí sola.','superheat'],
 ['Usar presión y nombres correctos','Buscá Tsat con presión absoluta: p absoluta = p manométrica + p atmosférica local. Recalentar es aportar calor después de una expansión parcial; desobrecalentar es reducir la temperatura del vapor mediante el dispositivo del diseño. No son sinónimos de sobrecalentar.','pressure']
],'No uses siempre 100 °C como temperatura de ebullición: depende de la presión.');
add('diagramas',0,[8,9,11],'Leer T-s, h-s y la expansión de la turbina','ts',[
 ['Dibujar la campana','En T-s, temperatura va en el eje vertical y entropía en el horizontal. La rama izquierda es líquido saturado, la derecha vapor saturado seco y el interior mezcla. Arriba se unen en el punto crítico; a la derecha aparece vapor sobrecalentado.','dome'],
 ['Distinguir las propiedades','La entalpía h combina energía interna y trabajo de flujo: h=u+pv. La entropía s permite describir reversibilidad e irreversibilidades. En h-s, o Mollier, la altura es entalpía: no se lee temperatura en ese eje.','axes'],
 ['Comparar expansión ideal y real','La expansión ideal adiabática y reversible es isentrópica: s permanece constante y su trazo en T-s es vertical. En una turbina real aproximadamente adiabática, las irreversibilidades aumentan s y reducen el trabajo respecto del ideal para iguales condiciones de entrada y presión final.','expansion'],
 ['Examinar la salida','Si el estado final entra a la campana, hay humedad; su cantidad se obtiene con propiedades, no midiendo a ojo este dibujo. Las gotas perjudican rendimiento y pueden erosionar álabes. Los trazos son cualitativos y no sustituyen tablas de vapor.','outlet']
],'No llames isotérmica a una expansión isentrópica: temperatura y entropía son propiedades diferentes.');
add('clasificacion',1,[13,14,15,16,17,25],'Clasificar antes de comparar una caldera','comparison',[
 ['Identificar qué circula por el tubo','En una acuotubular circula agua/mezcla por dentro y gases por fuera. En una humotubular, gases por dentro y agua alrededor. En ambas, la pared separa los fluidos y transmite calor.','waterTube'],
 ['Reconocer la construcción','Tubos rectos y curvos difieren en disposición, dilatación, accesos y conexiones con colectores. Los curvos permiten acomodar geometría y expansión; la conveniencia de cada solución depende del diseño, limpieza e inspección.','fireTube'],
 ['Relacionar con el servicio naval','El generador produce vapor para propulsión o auxiliares. En un buque importan peso, volumen, estabilidad del servicio, respuesta a maniobras, mantenimiento, seguridad y rendimiento. No se deduce capacidad sólo por tamaño o por una letra.','service'],
 ['Comparar con condiciones iguales','Las acuotubulares se adaptan a altas capacidades y presiones, pero exigen atender calidad de agua y control. La comparación con humotubulares debe incluir presión, producción, almacenamiento térmico, acceso y costo de mantenimiento. Clasificá además circulación y fuente de calor.','criteria']
],'Tener bomba de alimentación no convierte una caldera de circulación natural en circulación forzada.');
add('circulacion',1,[18,19],'Seguir la circulación natural','boiler',[
 ['Separación en el domo','La mezcla ascendente llega al colector superior. El vapor se separa y el agua queda disponible para volver al circuito. El domo contiene ambas fases y no es sólo un depósito de vapor.','upper'],
 ['Descenso de agua más densa','Los tubos descendentes, relativamente menos calentados según el diseño, conducen agua hacia zonas inferiores. La diferencia de densidad entre esta columna y la mezcla caliente aporta la fuerza motriz.','down'],
 ['Ascenso por los hervidores','El calentamiento forma burbujas en los tubos generadores. La mezcla menos densa asciende al domo y completa el circuito. Las pérdidas de carga se oponen a esa circulación.','risers'],
 ['Separar circulación y alimentación','Una bomba de circulación forzada impulsa el circuito evaporador. La bomba de alimentación agrega agua desde fuera para compensar el vapor extraído y las pérdidas. Son funciones distintas aunque ambas muevan agua.','feed']
],'No expliques el ascenso sólo diciendo que «el calor sube»: justificá densidades, columna hidrostática y recorrido.');
add('tipo-d',1,[20],'Reconstruir la caldera D del apunte','D',[
 ['Ubicar los dos colectores','En el diseño estudiado, el colector superior y el inferior se encuentran a un lado del hogar. Dibujalos antes de agregar tubos y distinguí espacio de vapor y de agua.','upper'],
 ['Cerrar el circuito de agua','Desde el domo, el agua baja por los descendentes y se distribuye hacia el colector inferior y las superficies alimentadas. Los tubos del piso y el cabezal de pared pertenecen al diseño representado.','down'],
 ['Marcar la mezcla ascendente','Los haces, pantalla y pared de agua reciben calor y devuelven mezcla al colector superior. Identificá sobre el apunte qué conexión alimenta cada superficie: la silueta D no basta para deducirla.','risers'],
 ['Separar gases y vapor','Los gases salen del hogar y ceden calor a las superficies posteriores; el vapor separado sigue su propio circuito hacia sobrecalentador y salida cuando existen. Verificá el orden en el esquema específico.','furnace']
],'Las flechas de gases no son tuberías de vapor. Usá el taller 3D para inspeccionar las conexiones del modelo.');
add('tipo-a',1,[21],'Reconstruir la caldera A del apunte','A',[
 ['Contar colectores','La disposición básica tiene un colector superior y dos inferiores laterales. Su posición y los haces que convergen hacia arriba permiten reconocer la A.','upper'],
 ['Alimentar los haces laterales','Los descendentes llevan agua hacia los colectores inferiores. Cada colector distribuye agua a su haz; el diseño del apunte incluye además una alimentación de la pared divisoria.','down'],
 ['Volver al domo','En las superficies calentadas se forma mezcla y asciende al colector superior. Allí se separan gotas y vapor. La alimentación nueva no sustituye este circuito recirculante.','risers'],
 ['Identificar las superficies de gases','Ubicá los hogares, la pared divisoria, el sobrecalentador y el economizador del esquema estudiado. Dibujá el recorrido de gases por fuera de los tubos y distinguí cada fluido por color.','furnace']
],'No dibujes un único colector inferior como si fuera una D: la A básica tiene dos inferiores.');
add('tipo-m',1,[22,23,24],'Reconocer la M sin inventar una geometría simétrica','M',[
 ['Tomar el plano como referencia','En la M del apunte hay un colector superior, un inferior central y otro lateral. Localizalos por sus conexiones; no la reconstruyas como una A invertida ni como dos mitades iguales.','upper'],
 ['Distinguir los hogares','El apunte diferencia hogar de sobrecalentado y hogar de saturado. Identificá qué superficies reciben calor de cada uno antes de describir gases o regulación.','furnace'],
 ['Seguir los circuitos','El agua desciende hacia colectores y cabezal; la mezcla retorna por las superficies generadoras. El vapor separado alimenta el sobrecalentador, que es otro circuito. La representación simplifica sus etapas.','risers'],
 ['Comparar con A y D','Compará cantidad/posición de colectores, hogares, acceso y superficies de intercambio. Para capacidad, presión, temperatura y aplicación necesitás datos del equipo: ninguna letra fija esos valores ni una lista universal de válvulas.','outlet']
],'La M mostrada es la del material consultado; otras familias comerciales pueden tener disposiciones diferentes.');
add('recuperacion',1,[26,27,28],'Distinguir recuperación, economizador y caldera mixta','recovery',[
 ['Encontrar la fuente de calor','En recuperación, los gases de escape del motor transfieren parte de su energía al circuito de agua/vapor. La capacidad depende del caudal y temperatura de escape y de las condiciones de operación del motor.','engine'],
 ['Preguntar si hay evaporación','Un economizador convencional precalienta agua de alimentación sin ser el evaporador. En uso naval, también se llama economizador a un generador por gases de escape: verificá si el equipo produce vapor y cómo circula el agua.','exchanger'],
 ['Reconocer el aporte del quemador','Una caldera compuesta o mixta combina aprovechamiento de escape y combustión propia según su diseño. Con motor a baja carga o parado puede requerirse aporte del quemador para cubrir la demanda.','burner'],
 ['Cerrar el balance de servicio','Compará producción disponible con consumidores. Seguí controles, circulación y protección de cada superficie en el plano: no presupongas que escape y quemador siempre operan juntos ni que tienen idéntico recorrido.','steam']
],'El nombre «economizador» por sí solo no demuestra que haya ni que no haya generación de vapor.');
add('construccion',2,[29,38],'Comprender hogar, envueltas y uniones','construction',[
 ['Delimitar el hogar','El hogar contiene la combustión y orienta la transferencia de calor. El refractario protege zonas expuestas y contribuye a las condiciones térmicas; no es el aislante externo ni un sustituto de la pared resistente a presión.','fire'],
 ['Separar envuelta y aislamiento','La envuelta contiene el recorrido de gases; el aislamiento reduce pérdidas y temperatura externa. Una doble envuelta puede servir a la distribución de aire o protección térmica según diseño. Identificá su función real en el plano.','insulation'],
 ['Reconocer las solicitaciones','Colectores y tubos soportan presión interna y tensiones debidas a temperatura, dilataciones, soportes y geometría de conexiones. El calentamiento desigual agrega esfuerzos aunque la presión esté dentro del régimen.','metal'],
 ['Explicar la unión del tubo','El mandrilado expande el extremo del tubo contra el alojamiento; el acampanado conforma su boca. Una unión soldada corresponde a un diseño y procedimiento calificados. No son reparaciones intercambiables elegidas sólo por conveniencia.','joint']
],'No atribuyas a la envuelta exterior la misma función resistente que al colector presurizado.');
add('domos',2,range(30,33),'Del colector inferior a la separación de gotas','boiler',[
 ['Distribuir desde abajo','El colector inferior recibe agua y la distribuye a tubos; las zonas bajas permiten reunir sedimentos y conectan extracciones de fondo. La función exacta de cada cabezal se comprueba por sus tubos conectados.','lower'],
 ['Distinguir tubos por su función','Los descendentes conducen principalmente agua hacia abajo; los hervidores calentados devuelven mezcla. La exposición al calor modifica densidad y circulación: no identifiques todos los tubos como si transportaran lo mismo.','risers'],
 ['Leer conexiones del domo','Ubicá entrada y distribución de alimentación, llegada de mezcla, salida de vapor, medición de nivel, presión, seguridad y purga superficial. El nivel normal deja volumen para separar vapor.','upper'],
 ['Separar no es sobrecalentar','Bafles, ciclones y secadores retiran gotas por cambios de dirección, fuerzas inerciales u otros mecanismos del diseño. Reducir humedad no equivale a elevar el vapor por encima de Tsat: eso exige aporte de calor en un sobrecalentador.','outlet']
],'Vapor saturado seco y vapor sobrecalentado no son dos nombres para el mismo estado.');
add('superficies',2,range(34,37),'Ordenar las superficies que recuperan calor','heat-train',[
 ['Sobrecalentar vapor separado','El sobrecalentador recibe vapor del domo y calor del lado de gases. Durante fuego con poco caudal, el metal puede perder refrigeración interna: su protección depende del diseño y de la circulación prevista.','superheater'],
 ['Distinguir recalentar y desobrecalentar','El recalentador recibe vapor que ya se expandió parcialmente y le aporta calor antes de otra expansión. El desobrecalentador reduce temperatura por el método instalado, por ejemplo intercambio o inyección controlada. Dibujá entradas y salidas diferentes.','reheater'],
 ['Aprovechar gases posteriores','El economizador entrega calor al agua de alimentación y el precalentador al aire de combustión. Ubicalos respecto del recorrido de gases real: no intercambies sus fluidos ni supongas que toda caldera incorpora ambos.','economizer'],
 ['Mantener superficies limpias','Los sopladores remueven depósitos del lado de gases. Antes de su empleo se verifican condiciones, fluido disponible, drenajes y restricciones del manual; el soplado incorrecto puede producir erosión o problemas térmicos.','airheater']
],'El orden mostrado es funcional y esquemático: conexiones y controles se verifican en el equipo estudiado.');
add('valvulas',2,[39,40,41,42,43,51,52],'Identificar una válvula por lo que hace','valves',[
 ['Aislar o regular','La principal comunica o aísla la salida de vapor. Una globo desplaza un obturador contra un asiento y puede controlar caudal; una compuerta despeja el paso y se emplea principalmente para aislamiento. La aplicación depende del diseño de válvula.','globe'],
 ['Permitir un solo sentido','Una retención abre por diferencia de presión favorable y cierra ante tendencia de retorno. SDNR significa screw-down non-return: combina cierre manual por husillo con función automática de retención. No todas las globo son SDNR.','check'],
 ['Separar regulación y protección','Una reductora controla presión aguas abajo; una reguladora modifica una variable de servicio; una seguridad alivia sobrepresión. En alimentación, cierre y retención pueden ser elementos separados. Clasificá cada símbolo por su función, no sólo por su aspecto.','safety'],
 ['Reconocer dispositivos auxiliares','Una trampa descarga condensado y limita pérdida de vapor vivo mediante su principio particular. Un bypass de calentamiento permite un paso previsto para calentar progresivamente. No sustituye una seguridad ni justifica cualquier apertura fuera del procedimiento.','trap']
],'Para D, A o M señalá las válvulas que realmente aparecen en el plano; no inventes una lista universal.');
add('seguridad',2,[44,45,46,50],'Entender medición y protección de presión','safety',[
 ['Medir sin confundir funciones','El manómetro informa presión; un sifón puede mantener condensado que protege al instrumento del vapor caliente. Los elementos de aislamiento permiten las comprobaciones previstas. La temperatura requiere su propio instrumento.','gauge'],
 ['Explicar la fuerza de apertura','En una seguridad de resorte, la fuerza debida a presión se opone a la del resorte. Al alcanzarse el ajuste, el obturador abre; su geometría puede favorecer apertura rápida. No se regula el servicio normal haciendo que descargue continuamente.','spring'],
 ['Distinguir apertura y cierre','La presión de cierre suele ser menor que la de apertura: esa diferencia es el blowdown. El ajuste depende de presión admisible, normativa aplicable y diseño; no se copia un porcentaje universal de otro equipo. Domo y sobrecalentador protegen sus espacios correspondientes.','disc'],
 ['Distinguir tres comprobaciones','Observar apertura/cierre verifica comportamiento; calibrar contrasta y ajusta con medios autorizados; probar acumulación verifica capacidad del conjunto para limitar el aumento de presión bajo condiciones de ensayo especificadas. No son la misma prueba.','discharge']
],'Nunca deduzcas el ajuste de seguridad sólo a partir de la presión habitual de trabajo.',['safety']);
add('purgas-nivel',2,[47,48,49],'Distinguir purgas, venteos, drenajes y nivel','boiler',[
 ['Retirar desde el fondo','Las extracciones inferiores actúan sobre lodos y sedimentos en colectores/cabezales. Su conexión y receptor se identifican en el plano; no se trata de una salida de vapor principal.','lower'],
 ['Extraer cerca de la superficie','La purga superficial o continua ayuda a controlar concentración e impurezas del agua. No arranca por sí sola incrustaciones adheridas ni cumple la misma función que la extracción de fangos.','upper'],
 ['Dar salida al aire y al condensado','Los venteos permiten evacuar aire durante etapas previstas; los drenajes retiran líquido acumulado en sobrecalentador y líneas. El criterio de cierre depende de condiciones verificadas y procedimiento, no de un tiempo universal.','outlet'],
 ['Comprobar el indicador','Un visor suele conectar espacio de vapor y de agua mediante válvulas y dispone de purga de comprobación. La comunicación libre de ambas tomas y la comparación con indicación independiente permiten evaluar confiabilidad. Ante discrepancia, no inventes el nivel real.','level']
],'Una lectura invisible puede corresponder a lleno, vacío o conexión obstruida; no diagnostiques sólo por apariencia.');
add('transferencia',3,[53,54],'Seguir el calor desde la llama hasta el agua','wall',[
 ['Radiación desde la combustión','La llama y los gases calientes intercambian energía radiante con las superficies expuestas del hogar. No necesita contacto material y tiene especial importancia en zonas de alta temperatura.','fire'],
 ['Convección del lado de gases','Los gases que recorren los haces transfieren calor a la superficie exterior. Hollín adherido agrega una resistencia entre gases y metal, reduciendo el intercambio para las mismas condiciones.','soot'],
 ['Conducción a través del metal','El calor atraviesa la pared del tubo por conducción. Su espesor y conductividad intervienen en la resistencia térmica; el flujo no significa que gases y agua se mezclen.','metal'],
 ['Transferencia al agua y depósitos','En la cara interna, convección y ebullición retiran calor. Una incrustación dificulta ese retiro y puede elevar la temperatura del metal hasta dañarlo, aun cuando el agua esté a su temperatura de saturación.','scale']
],'No confundas hollín exterior con incrustación interior: ambos aíslan, pero tienen origen y tratamiento diferentes.');
add('combustion',3,[55,56,62,63,64],'Relacionar aire, combustible y estabilidad de llama','combustion',[
 ['Preparar mezcla y condiciones','Combustible, oxígeno, mezcla suficiente, temperatura y tiempo de reacción permiten una combustión estable. El registro distribuye aire alrededor del pulverizador; el ventilador aporta el movimiento del circuito de tiro.','air'],
 ['Distribuir el combustible','Pulverizar crea gotas que pueden calentarse y evaporarse para mezclarse con aire. Un rocío fino y uniforme es deseable; un chorro o gotas gruesas pueden producir combustión incompleta y depósitos.','nozzle'],
 ['Ajustar la relación de aporte','Aire insuficiente favorece combustión incompleta; exceso innecesario arrastra calor hacia chimenea. Tiro natural depende del efecto de chimenea; forzado impulsa aire y el inducido extrae gases. El precalentador aprovecha calor de escape.','flame'],
 ['Interpretar síntomas y protecciones','Humo negro o llama inestable requieren relacionar combustible, aire, pulverización y carga. Análisis de gases y temperatura de chimenea aportan evidencia. La cadena de permisos y detector de llama debe impedir aporte inseguro de combustible y cortar cuando corresponda.','exhaust']
],'El color de humo aislado no alcanza para diagnosticar una causa única.');
add('combustible',3,range(57,61),'Preparar combustible antes de pulverizar','fuel',[
 ['Desde almacenamiento al servicio','Seguí tanques, sedimentación/tratamiento y tanque de servicio según instalación. Separar agua y sólidos reduce problemas posteriores. Poder calorífico informa energía disponible; agua y sedimentos reducen la fracción útil y afectan el servicio.','tank'],
 ['Impulsar, calentar y filtrar','La bomba entrega caudal y presión. El calentamiento de combustibles viscosos busca la viscosidad especificada a la entrada del quemador. Los filtros retienen sólidos; temperatura, presión y pérdida de carga permiten interpretar restricciones.','heater'],
 ['Conocer propiedades distintas','Flash point caracteriza aparición de vapores inflamables bajo ensayo; el punto de combustión sostenida requiere persistencia de la llama y el de fluidez indica comportamiento a baja temperatura. Cenizas, residuo y azufre se relacionan con depósitos, emisiones y corrosión bajo condiciones apropiadas.','filter'],
 ['Formar el rocío','La pulverización mecánica usa presión y geometría del paso para dividir el líquido. La asistida usa vapor o aire como medio atomizante adicional: identificá ambas entradas. Viscosidad, presión, boquilla y medio atomizante deben corresponder al diseño.','nozzle']
],'No uses un valor universal de temperatura para todos los combustibles ni confundas combustible con aceite lubricante.');
add('alimentacion',4,[65,66,67,68,69,75,76,77,78],'Reconstruir el retorno completo del agua','feed',[
 ['Condensar y recoger','El escape de turbina llega al condensador de superficie. Vapor/condensado y agua de refrigeración permanecen separados por paredes. El hotwell reúne condensado y ofrece la reserva para aspiración de su bomba de extracción.','condenser'],
 ['Extraer y acondicionar','La bomba de condensado envía agua hacia los calentadores y el desaireador presentes en el esquema. No es la misma bomba que vence la presión de caldera. Ubicá cada equipo y sus corrientes de calentamiento sin inventar etapas faltantes.','condensate'],
 ['Elevar presión hacia la caldera','Desde el tanque/desaireador, la bomba de alimentación descarga a través de válvulas y economizador cuando existe hasta el domo. Debe vencer presión de caldera, diferencias de altura y pérdidas de carga. La retención evita retorno al caer la presión de bomba.','feedPump'],
 ['Mantener disponibilidad','La recirculación de caudal mínimo, si existe, protege a la bomba cuando el consumo es pequeño. Bombas de reserva, aislamiento y retenciones permiten la disposición prevista ante fallas; la transferencia se explica con el plano y sus permisos.','boiler']
],'La bomba de alimentación normalmente no aspira directamente del condensador en este circuito con desaireador.');
add('desaireacion',4,range(70,74),'Desairear sin provocar problemas en aspiración','deaerator',[
 ['Poner agua y vapor en contacto','La desaireación térmica calienta el agua y facilita la liberación de gases disueltos. Bandejas, pulverización u otros elementos aumentan contacto según diseño; el vapor entrega calor al agua.','water'],
 ['Evacuar los gases separados','Separar gases no alcanza si permanecen atrapados. El venteo previsto los retira; el almacenamiento inferior aporta reserva de agua acondicionada. No confundas esa función con condensar el escape principal de turbina.','vent'],
 ['Distinguir presión y ubicación','Un desaireador presurizado trabaja bajo condiciones de presión/temperatura propias; un tanque atmosférico no es equivalente. La elevación respecto a la bomba puede aportar altura estática a la aspiración.','tank'],
 ['Explicar cavitación y NPSH','Si la presión local cae por debajo de la de vapor del agua aparecen burbujas que luego colapsan. Agua caliente, pérdidas de aspiración y poca altura disponible reducen margen. NPSH disponible se compara con el requerido y el margen especificado para la bomba.','pump']
],'La cavitación de una bomba no se corrige explicando simplemente que «entró aire»: vapor del líquido y aire externo son fenómenos distintos.',['cavitation']);
add('control-agua',4,[79,80,81,82],'Interpretar nivel aparente y calidad de agua','level-control',[
 ['Un elemento','El regulador usa nivel como señal para modificar alimentación. Es sencillo, pero el nivel contiene efectos de inventario y de volumen de burbujas: no siempre cambia al mismo tiempo que la masa de agua.','level'],
 ['Dos y tres elementos','Dos elementos combinan nivel y caudal de vapor; tres agregan caudal de agua de alimentación. La demanda de vapor anticipa la reposición y la medición de agua permite contrastar el flujo real, según la estrategia del sistema.','flows'],
 ['Comprender swell y shrink','Una caída de presión puede expandir burbujas y subir el nivel indicado aunque se pierda masa: swell. Al aumentar presión o condensarse burbujas, el nivel puede bajar: shrink. Relacioná nivel, presión y caudales antes de interpretar una variación.','bubbles'],
 ['Controlar impurezas','Dureza favorece depósitos; oxígeno contribuye a corrosión; sales elevan concentración y pueden favorecer arrastre; aceite perjudica superficies. Una entrada salina al condensado se investiga con muestras, conductividad/cloruros y localización de pérdidas. Tratamiento y purgas se ajustan al programa del equipo.','samples']
],'Ni un nivel momentáneamente alto garantiza inventario suficiente ni cloruros significa automáticamente incrustación.',['level']);
add('preparar-caldera',5,range(83,87),'Justificar las verificaciones antes del encendido','sequence',[
 ['Liberar el equipo después del mantenimiento','Confirmá inspección, retiro de herramientas, cierres, conexiones, integridad y condición de retorno al servicio. El propósito es evitar encender una instalación incompleta o con trabajos todavía abiertos.','one'],
 ['Asegurar agua y alimentación','Comprobá calidad de agua, nivel inicial indicado por el procedimiento y confiabilidad de instrumentos. Verificá que la alimentación y sus reservas estén disponibles antes de exigir producción de vapor.','two'],
 ['Contrastar cada válvula con el plano','Identificá alimentación, vapor, purgas, venteos y drenajes; justificá su disposición inicial con el manual. Nombrar «todas abiertas» o «todas cerradas» no explica funciones ni representa una maniobra válida.','three'],
 ['Comprobar servicios y permisos','Aire, combustible, atomización cuando corresponde, energía, control y protecciones deben estar disponibles. La puesta en marcha continúa con barrido, encendido, calentamiento y comunicación sólo cuando sus condiciones se verifican.','four']
],'Esta secuencia organiza la explicación oral; no fija posiciones de válvulas ni tiempos de una caldera no identificada.');
add('encendido',5,range(88,92),'Entender barrido, encendido y calentamiento','sequence',[
 ['Eliminar mezclas remanentes','El barrido renueva el ambiente del hogar antes de admitir combustible. Su cumplimiento exige las condiciones verificadas por el sistema, como tiro y secuencia prevista; no se demuestra solamente contando unos segundos.','one'],
 ['Confirmar encendido y llama','El sistema debe supervisar el establecimiento de llama. Una falla de encendido o pérdida de llama exige la respuesta de protección y la investigación previstas; repetir intentos sin nuevo barrido y permisos puede acumular combustible.','two'],
 ['Aumentar gradualmente el aporte','El calentamiento progresivo limita diferencias de dilatación y tensiones en metal y refractarios. Venteos evacuan aire y se cierran cuando el procedimiento y las condiciones lo indican, no por una regla universal.','three'],
 ['Cuidar superficies con poco caudal','Durante el arranque hay fuego pero puede haber poco vapor circulando por el sobrecalentador. Identificá circulación, drenajes y protección del diseño; la ausencia de carga no significa ausencia de riesgo térmico.','four']
],'No sustituyas la confirmación de llama por observar que la presión comenzó a subir.');
add('comunicar',5,range(93,97),'Pasar de calentamiento a servicio con carga','sequence',[
 ['Calentar y drenar líneas','El vapor que toca metal frío condensa. Drenar por el sistema previsto evita acumular líquido; un tapón arrastrado puede producir golpe de ariete. El calentamiento gradual también limita dilataciones desiguales.','one'],
 ['Verificar condiciones de comunicación','Comunicar significa conectar la caldera al colector de vapor. Contrastá presión, temperatura, drenaje y disposición de válvulas con el procedimiento y con la condición del colector receptor.','two'],
 ['Incorporar carga de forma coordinada','La demanda debe ser compatible con combustión y alimentación disponibles. Vigilá presión, nivel, caudales, temperatura de vapor y estabilidad de llama; coordiná el aporte con los consumidores y otras calderas.','three'],
 ['Interpretar una variación de demanda','Mayor consumo puede reducir presión, cambiar volumen de burbujas y exigir más agua y calor. Relacioná la acción de controles con swell/shrink; el nivel indicado no sigue de forma instantánea al inventario. En guardia se observan tendencias, no sólo valores aislados.','four']
],'Una caída de presión no autoriza por sí sola aumentar fuego: comprobá nivel y alimentación.');
add('averias-caldera',5,[98,99,100],'Distinguir bajo nivel, arrastre y tubo averiado','boiler',[
 ['Bajo nivel y pérdida de indicación','Diferenciá un nivel bajo medido, el límite peligroso del equipo y una indicación no confiable. La protección debe impedir calentar superficies sin refrigeración suficiente. Aportar agua indiscriminadamente a una caldera sobrecalentada puede agravar la situación.','level'],
 ['Alto nivel y arrastre','Sobrellenado, cambios de carga y condiciones del agua pueden llevar gotas e impurezas con el vapor. El riesgo se extiende a sobrecalentador, líneas y turbina; separar agua en el domo no resuelve cualquier causa de arrastre.','upper'],
 ['Buscar evidencia de rotura','Pérdida anormal de agua, dificultad para sostener nivel, ruidos o vapor en zonas indebidas pueden sugerir un tubo averiado. Son indicios a correlacionar; no prueban por sí solos dónde está la falla.','risers'],
 ['Relacionar protección e inspección','Retirada del servicio y respuesta de emergencia se deciden por el procedimiento y la gravedad. Antes de inspeccionar se requieren aislamiento, ausencia de presión, enfriamiento y condiciones de acceso verificadas. El visor del taller permite ubicar las zonas afectadas.','furnace']
],'No confundas una lista de síntomas con un procedimiento completo de emergencia.');
add('parar-caldera',5,range(101,104),'Explicar parada, enfriamiento y conservación','sequence',[
 ['Retirar la carga normalmente','La parada normal coordina consumidores, reduce carga y retira la caldera del servicio en el orden previsto. El corte de combustible elimina el aporte principal, pero el equipo conserva calor y presión.','one'],
 ['Distinguir una emergencia','Fallas de llama, alimentación, tiro o control pueden exigir actuación rápida de protecciones. La prioridad y disposición posterior difieren de una parada normal; no se espera completar una reducción gradual si el sistema requiere disparo.','two'],
 ['Vigilar el enfriamiento','Continuá controles y auxiliares que indique el diseño. Un enfriamiento brusco introduce tensiones; vaciar caliente y presurizado no es una forma universal de acelerar la parada. Verificá presión, temperatura y aislamiento antes de intervenir.','three'],
 ['Elegir conservación según condición','Conservación húmeda mantiene condiciones químicas controladas; seca procura evitar humedad y corrosión con el equipo preparado. Duración, ambiente y fabricante determinan método. El retorno exige inspección, restitución de conexiones y comprobaciones.','four']
],'La parada no termina cuando se apaga la llama: quedan energía almacenada y riesgos de aislamiento.');
add('etapas-turbina',6,range(105,110),'Seguir la expansión y la entrega de par','turbine',[
 ['Entrar a las partes fijas','La carcasa contiene el recorrido; toberas, álabes fijos y diafragmas distribuyen y orientan vapor. Parte de la caída de entalpía se transforma en velocidad antes de llegar al rotor.','stator'],
 ['Transferir cantidad de movimiento','Los álabes móviles cambian dirección y magnitud de la velocidad del vapor. La componente tangencial del intercambio produce par sobre el rotor y el eje; la energía sale como potencia mecánica.','rotor'],
 ['Comparar acción y reacción','En una etapa ideal de acción la caída de presión ocurre principalmente en partes fijas; en reacción también existe expansión en las móviles. Una etapa combina filas fijas y móviles. Escalonar presión reparte expansión; escalonar velocidad aprovecha una aceleración en sucesivas filas móviles.','pressure'],
 ['Ubicar etapas y destino del escape','En alta y baja presión cambian densidad y volumen específico; las áreas de paso suelen crecer hacia baja presión. Una turbina de condensación descarga al condensador, una de contrapresión a un servicio a mayor presión y las extracciones derivan vapor intermedio.','exhaust']
],'No expliques par sólo por «presión que empuja»: incluí el cambio de velocidad y las partes que lo provocan.');
add('velocidades',6,[111,112,113],'Construir el triángulo de velocidades','triangle',[
 ['Elegir el sistema de referencia','C es la velocidad absoluta del vapor respecto a la carcasa. U es la velocidad periférica del álabe en el radio considerado. W es la velocidad del vapor relativa al álabe móvil. Son vectores, con dirección y sentido.','absolute'],
 ['Cerrar el triángulo','Dibujá U y, desde su punta, W. El vector desde el origen hasta el extremo final es C: C = U + W. Prepará un triángulo a la entrada y otro a la salida, usando la misma convención de signos.','relative'],
 ['Relacionar con trabajo','La variación de componente tangencial de C explica intercambio de momento angular y par. Para igual radio, el trabajo específico ideal se relaciona con U por la diferencia de componentes tangenciales entre entrada y salida. No alcanza comparar sólo módulos de velocidad.','peripheral'],
 ['Incorporar pérdidas reales','Rozamiento, fugas, humedad y operación fuera de diseño reducen trabajo útil. La trayectoria real y el ángulo de incidencia pueden diferir de los ideales. El triángulo cualitativo no proporciona por sí solo rendimiento ni potencia numérica.','work']
],'No sumes C, U y W como tres velocidades escalares: cerrá el triángulo vectorial.',['triangles']);
add('mecanica-turbina',6,[114,115,116],'Sostener, sellar y transmitir el giro','shaft',[
 ['Sostener radialmente','Los cojinetes radiales limitan desplazamientos transversales del eje y mantienen su posición respecto a la carcasa. La lubricación y holguras previstas permiten la película que separa superficies.','radial'],
 ['Controlar el empuje axial','El cojinete de empuje ubica axialmente el rotor y absorbe esfuerzos en esa dirección. No cumple la misma función que el radial; el desplazamiento axial se vigila por su relación con holguras internas.','thrust'],
 ['Controlar fugas en los sellos','Los laberintos restringen el flujo por pasos sucesivos. En zonas presurizadas interesa limitar fuga de vapor; bajo vacío interesa evitar entrada de aire. El vapor de sellado y sus extracciones dependen del régimen y diseño.','seal'],
 ['Transmitir a la carga','El acoplamiento conecta ejes y el reductor adapta velocidad/par entre turbina y hélice u otra máquina. Una turbina puede girar a muchas más revoluciones que la hélice; reducir velocidad no equivale necesariamente a invertirla.','gear']
],'El virador gira lentamente para acondicionamiento térmico; no es el equipo de propulsión marcha atrás.');
add('aceite',7,[117,118,119,120,121,122,123,124,126],'Seguir aceite hasta cada cojinete y de regreso','oil',[
 ['Asegurar reserva y presión','Desde el tanque se abastecen bombas principal, auxiliar o de emergencia según instalación. El aceite reduce rozamiento y también evacua calor. Su viscosidad, estabilidad, limpieza y separación de agua deben corresponder a la especificación de turbina.','tank'],
 ['Acondicionar antes de distribuir','Filtros retienen partículas y enfriadores regulan el estado térmico. Diferencia de presión en filtro y temperaturas de entrada/salida ayudan a identificar restricciones y desempeño. La conmutación de equipos duplicados debe mantener el suministro según diseño.','condition'],
 ['Llegar al punto lubricado','Cada cojinete necesita caudal y condiciones adecuados. Presión normal en el colector no prueba que una rama esté libre ni que el aceite llegue correctamente. El circuito de aceite de control cumple otra función, aunque puede compartir parte de la instalación.','bearings'],
 ['Mantener retorno y continuidad','El retorno por gravedad o rebalse necesita disposición y drenaje libres. Un tanque elevado, si existe, puede aportar reserva por altura y no es el tanque principal de retorno. Lubricación debe estar disponible antes del giro, a régimen y durante desaceleración/enfriamiento según procedimiento.','return']
],'No mandes el retorno de aceite al condensador ni al desaireador: son circuitos diferentes.');
add('aceite-contaminado',7,[125],'Investigar agua, espuma o aire en el aceite','oil',[
 ['Describir qué se observa','Diferenciá agua libre, emulsión, espuma superficial y aire arrastrado. Una apariencia semejante puede tener causas diferentes: tomá la observación como inicio de investigación, no como diagnóstico cerrado.','tank'],
 ['Localizar posibles ingresos','Revisá intercambiadores, sellos y puntos expuestos según el equipo. La dirección de una pérdida depende de las presiones de ambos lados; no atribuyas automáticamente toda agua en aceite al mismo componente.','condition'],
 ['Relacionar con lubricación','Contaminación y aireación pueden perjudicar película, transferencia térmica y estabilidad del suministro. Compará presión, temperatura, caudal y condición del lubricante con análisis y tendencias.','bearings'],
 ['Cerrar la causa y el efecto','Retirar contaminación sin corregir su origen permite que vuelva. La respuesta, depuración, cambio y limpieza se definen por estado del equipo y especificación del aceite; no se improvisan mezclas de lubricantes.','return']
],'Espuma no demuestra por sí sola que haya entrado agua: explicá cómo lo comprobarías.');
add('vacio',7,range(127,130),'Relacionar condensador, vacío y sellado','condenser',[
 ['Condensar sin mezclar corrientes','El vapor cede calor y condensa sobre superficies refrigeradas. El agua de circulación pasa por su circuito separado. La presión de escape condiciona la expansión útil en la turbina.','steam'],
 ['Evacuar calor','Obstrucciones, bajo caudal de agua de circulación o alta temperatura de refrigeración reducen capacidad de condensación y pueden elevar presión del condensador. Mirá temperaturas, caudales y estado de superficies.','cooling'],
 ['Retirar no condensables','Eyectores o bombas de vacío extraen aire y otros gases. Éstos no se eliminan sólo condensando vapor y pueden perjudicar transferencia. Bajo vacío pueden ingresar por sellos, uniones y otros puntos de falta de estanqueidad.','air'],
 ['Conectar los auxiliares correctos','Vapor de sellado limita ingreso de aire en los extremos bajo vacío; su sistema puede tener extracción propia. El condensado vuelve por bomba y desaireador, mientras el agua de circulación retorna a su fuente. Identificá las conexiones reales antes de unir flechas.','condensate']
],'La bomba de condensado extrae líquido: no reemplaza al eyector de aire.');
add('arranque-turbina',8,range(131,134),'Preparar la turbina antes de tomar carga','sequence',[
 ['Verificar y lubricar','Confirmá condición de equipo, instrumentación, protecciones, suministro de aceite y auxiliares. La película lubricante debe poder establecerse antes de exigir giro y mantenerse durante el proceso.','one'],
 ['Acondicionar con virador','El giro lento favorece uniformidad térmica durante calentamiento/enfriamiento cuando el procedimiento lo requiere. El enclavamiento debe impedir admitir vapor de marcha con el virador engranado.','two'],
 ['Preparar vapor, drenajes y vacío','Calentá progresivamente y evacuá condensados según el procedimiento. Sellado y vacío se establecen cuando corresponden al diseño. Agua acumulada y dilatación desigual pueden dañar partes internas.','three'],
 ['Vigilar el giro inicial','Durante aceleración observá vibraciones, temperaturas, desplazamiento axial y condiciones del aceite. Las velocidades críticas y sus criterios de paso son datos del fabricante; no se inventa un régimen de permanencia.','four']
],'El virador no sustituye al motor principal ni proporciona marcha atrás propulsora.');
add('proteccion-turbina',8,[135,136],'Separar regulación normal y disparo','control',[
 ['Regular a régimen','El regulador modifica admisión para mantener la variable de servicio frente a cambios de carga. Una reducción súbita de carga puede acelerar el conjunto si continúa entrando demasiado vapor.','sensor'],
 ['Detectar una condición peligrosa','La protección por sobrevelocidad tiene función distinta de la regulación normal. Compara velocidad con su criterio de disparo definido; otros parámetros pueden tener alarmas o disparos según diseño.','logic'],
 ['Cortar admisión','La válvula de cierre rápido interrumpe aporte de vapor cuando actúa la cadena de protección. No confundas una alarma, que avisa, con un disparo, que ejecuta una acción de protección.','valve'],
 ['Continuar los auxiliares necesarios','La parada normal reduce carga coordinadamente; la emergencia prioriza la protección. Aunque se corte vapor, rotor y metal conservan energía: lubricación, enfriamiento y virador continúan cuando el procedimiento lo exige, coordinados con la caldera.','rotor']
],'Cortar vapor no significa que el rotor se haya detenido ni que pueda cortarse inmediatamente el aceite.');
add('marcha-atras',8,range(137,144),'Explicar marcha atrás con el recorrido correcto','astern',[
 ['Identificar la solución propulsora','Con hélice de paso fijo, una planta reversible puede usar turbina o sección de ciar. La clase sitúa esa sección en el conjunto de baja presión del diseño explicado. No generalices su ubicación a todas las plantas.','ahead'],
 ['Seguir el vapor de ciar','La distribución admite vapor a toberas y álabes preparados para producir par en el sentido requerido. Dibujá admisión y escape de adelante y atrás como recorridos distintos; invertir simplemente el flujo en los mismos álabes no reproduce esa función.','astern'],
 ['Relacionar maniobra y caldera','La transición incluye reducción/corte de admisión, control de giro, drenajes, calentamiento y enclavamientos del equipo. Una demanda brusca de ciar puede aumentar mucho consumo respecto de potencia útil y perturbar presión, nivel aparente y alimentación.','gear'],
 ['Comparar con paso controlable','Una hélice de paso controlable puede invertir empuje cambiando el paso sin invertir el sentido del eje. Un reductor no es automáticamente inversor y el virador no propulsa. Sin empuje esperado, contrastá orden, admisión, giro, paso y transmisión con indicaciones.','propeller']
],'El esquema es funcional: el sentido de flechas representa circuitos seleccionados, no una maniobra automática autorizada.');
add('fluido-termico',9,range(145,148),'Transportar calor mediante un fluido térmico','thermal',[
 ['Impulsar el circuito','Una bomba mantiene el fluido circulando por calentador y consumidores. El circuito puede suministrar calor a servicios navales sin usar evaporación/condensación de agua como mecanismo principal.','pump'],
 ['Aportar y entregar calor','El calentador aumenta temperatura y el consumidor recibe calor a través de una superficie. El fluido retorna a menor temperatura y vuelve a calentarse. Caudal y diferencia de temperatura determinan el calor transportado.','heater'],
 ['Admitir expansión','El tanque de expansión absorbe cambios de volumen y cumple funciones adicionales según diseño. Su conexión se toma del plano, frecuentemente relacionada con la aspiración de bomba; no es un desaireador de agua de alimentación de caldera.','expansion'],
 ['Cuidar el fluido','Se controlan límites térmicos y condición del fluido: degradación, oxidación, contaminación y viscosidad afectan servicio. Agua contaminante puede vaporizar y alterar circulación/presión. La compatibilidad y el análisis se rigen por proveedor y fabricante.','consumer']
],'Ampliación didáctica del programa: no se presenta como un apunte específico de Daldin.',['thermal']);
add('operar-fluido',9,[149,150],'Verificar circulación antes de aplicar calor','sequence',[
 ['Preparar nivel y camino de flujo','Confirmá estado del fluido, reserva, disposición de válvulas, ausencia de fugas y disponibilidad de bomba e instrumentos. El circuito no debe quedar sin camino de circulación al calentador.','one'],
 ['Probar caudal antes de encender','El permiso de calentamiento debe depender de las condiciones del sistema, incluida circulación suficiente. Bajo caudal puede elevar la temperatura local del fluido y de las superficies aunque la temperatura promedio no parezca extrema.','two'],
 ['Vigilar operación y protecciones','Seguimiento de caudal, temperaturas, nivel y estanqueidad permite detectar bajo flujo, sobretemperatura, fuga o falla de bomba. Alarmas e interbloqueos se describen por su causa y por la acción prevista, sin inventar consignas.','three'],
 ['Retirar calor residual al parar','Cortar el fuego no elimina el calor acumulado. Se mantiene circulación durante el período y hasta las condiciones indicadas por el fabricante; después se completa la parada. Inspección, análisis del fluido y mantenimiento reducen degradación y fallas.','four']
],'No detengas conceptualmente bomba y quemador como si fueran un único interruptor: justificá la extracción del calor residual.',['thermal']);
module.exports={modules};
